// Scheduled Job - runs daily
var gr = new GlideRecord('sysapproval_approver');
gr.addQuery('state', 'requested');
gr.addQuery('source_table', 'sc_req_item');
gr.query();
while (gr.next()) {
  var created = gr.getValue('sys_created_on');
  var createdDT = new GlideDateTime(created);
  var now = new GlideDateTime();
  var diff = GlideDateTime.subtract(createdDT, now);
  var days = diff.getRoundedDayPart();
  if (days % 3 == 0 && days > 0) {
    // Send reminder notification
    gs.eventQueue(
      'approval.reminder',
      gr,
      gr.getValue('approver'),
      days
    );
  }
}

